# --- Oracle: paint integer points into a set, read off maximal runs ---

RNG = random.Random(12345)


def oracle(intervals):
    points = set()
    for start, end in intervals:
        points.update(range(start, end + 1))
    runs = []
    for p in sorted(points):
        if runs and p == runs[-1][1] + 1:
            runs[-1] = (runs[-1][0], p)
        else:
            runs.append((p, p))
    return runs


def test_fuzz_against_paint_oracle():
    for _ in range(300):
        n = RNG.randint(0, 12)
        ivs = []
        for _ in range(n):
            a = RNG.randint(-10, 10)
            b = RNG.randint(-10, 10)
            ivs.append((min(a, b), max(a, b)))
        expected = oracle(ivs)
        got = merge(ivs)
        assert got == expected, f"input={ivs!r} expected={expected!r} got={got!r}"
